type IndexItem={id:string;question:string;status:string;created_at:string;turn_index:number};
type View='ask'|'sources'|'history';
type ReaderTarget={id:string;evidence?:AnswerEvidence;role?:'published'|'retrieved';page?:number;answerId?:string;claimText?:string};
type WorkspaceState={draft?:string;source_ids?:string[];active_answer_id?:string;selected_source_id?:string;selected_page?:number;scroll_top?:number;branch_id?:string};
const sourceIcon=(source:Source)=>source.kind==='database'?<Database size={19}/>:source.kind==='spreadsheet'?<Table2 size={19}/>:<FileText size={19}/>;
const sourceStatus:Record<string,string>={queued:'等待处理',processing:'正在解析',ready:'可用',attention:'可用 · 有提示',failed:'需要处理',cancelled:'已取消'};
function tabId(){let id=tabStorage.getItem('zhiheng-tab-v2');if(!id){id=crypto.randomUUID().replaceAll('-','').slice(0,16);tabStorage.setItem('zhiheng-tab-v2',id);}return id;}
function pendingPatch(projectId:string,answer?:ResearchAnswer|null):ContextPatch[]{
 if(!answer||!canContinueAnswer(answer))return [];try{const saved=JSON.parse(tabStorage.getItem(`zhiheng-patch:${projectId}:${answer.id}`)??'null');return saved?.revision===answer.context_revision&&Array.isArray(saved.patch)?saved.patch:[];}catch{return [];}
}

// A new analysis keeps its own scope, independent of the history currently open.
function availableNewAnalysisScope(projectId:string,ids:unknown,sources:Source[]):string[]{
 const usable=new Set(sources.filter(source=>source.project_id===projectId&&source.usable&&!source.archived).map(source=>source.id));
 return Array.isArray(ids)?Array.from(new Set(ids.filter((id):id is string=>typeof id==='string'&&usable.has(id)))).slice(0,12):[];
}
function readNewAnalysisScope(projectId:string,sources:Source[],fallback:unknown=[]):string[]{
 try{const saved=tabStorage.getItem(`zhiheng-scope:${projectId}:new`);return availableNewAnalysisScope(projectId,saved===null?fallback:JSON.parse(saved),sources);}
 catch{return availableNewAnalysisScope(projectId,fallback,sources);}
}
function saveNewAnalysisScope(projectId:string,ids:unknown,sources:Source[]):string[]{
 const selected=availableNewAnalysisScope(projectId,ids,sources);tabStorage.setItem(`zhiheng-scope:${projectId}:new`,JSON.stringify(selected));return selected;
}

